// Server is a general purpose HTTP server Runnable for a manager
// to serve some internal handlers such as health probes, metrics and profiling.
type Server struct {
	// Kind is the kind of the server.
	Kind string

	// Log is the logger the server will use.
	Log logr.Logger

	// Server is the underlying server.
	Server *http.Server

	// Listener is the net.Listener the server will listen on.
	Listener net.Listener

	// ShutdownTimeout is the timeout that the server will use for shutdown.
	ShutdownTimeout time.Duration

	// NeedLeaderElectionIn indicates whether the server should start without leader election.
	// If this is set to true, the server will be started without leader election.
	NeedLeaderElectionIn bool

	// MetricsPath is the path to the metrics endpoint.
	// ...
}

// NewServer returns a new server that can be added to the manager.
func NewServer(handler http.Handler, opts ...Option) *Server {
	s := &Server{...}
	for _, o := range opts {
		o(s)
	}
	return s
}

// Option is an option for the server.
type Option func(*Server)

// WithListener sets the listener for the server.
func WithListener(l net.Listener) Option {
	return func(s *Server) {
		s.Listener = l
	}
}

// WithAddress sets the address for the server.
func WithAddress(addr string) Option {
	return func(s *Server) {
		s.Listener = ...
	}
}

// WithShutdownTimeout sets the shutdown timeout for the server.
func WithShutdownTimeout(timeout time.Duration) Option {
	return func(s *Server) {
		s.ShutdownTimeout = timeout
	}
}

// WithNeedLeaderElection sets the NeedLeaderElection flag for the server.
func WithNeedLeaderElection() Option {
	return func(s *Server) {
		s.NeedLeaderElection = true
	}
}

// WithLogger sets the logger for the server.
func WithLogger(logger logr.Logger) Option {
	return func(s *Server) {
		s.Log = logger
	}
}

// WithKind sets the kind of the server.
func WithKind(kind string) Option {
	return func(s *Server) {
		s.Kind = kind
	}
}

func (s *Server) Start(ctx context.Context) error {
	log := s.Log.WithValues("kind", s.Kind, "addr", s.Listener.Addr())

	serverShutdown := make(chan struct{})
	go func() {
		<-ctx.Done()
		log.Info("shutting down server")
		if err := s.Server.Shutdown(context.Background()); err != nil {
			log.Error(err, "error shutting down server")
		}
		close(serverShutdown)
	}()

	log.Info("starting server")
	if err := s.Server.Serve(s.Listener); err != nil && !errors.Is(err, http.ErrServerClosed) {
		return err
	}

	<-serverShutdown
	return nil
}

func (s *Server) NeedLeaderElection() bool {
	return s.NeedLeaderElection
}
