func TestTempVerifyServerRouting(t *testing.T) {
	errCh := make(chan error)

	r := newRunnables(defaultBaseContext, errCh)
	if err := r.Add(&Server{}); err != nil {
		t.Fatal(err)
	}
	if len(r.HTTPServers.startQueue) != 1 {
		t.Errorf("expected OnlyServeWhenLeader=false server in HTTPServers group, got %d", len(r.HTTPServers.startQueue))
	}
	if len(r.LeaderElection.startQueue) != 0 {
		t.Errorf("expected no LeaderElection queue entries, got %d", len(r.LeaderElection.startQueue))
	}

	r2 := newRunnables(defaultBaseContext, errCh)
	if err := r2.Add(&Server{OnlyServeWhenLeader: true}); err != nil {
		t.Fatal(err)
	}
	if len(r2.LeaderElection.startQueue) != 1 {
		t.Errorf("expected OnlyServeWhenLeader=true server in LeaderElection group, got %d", len(r2.LeaderElection.startQueue))
	}
	if len(r2.HTTPServers.startQueue) != 0 {
		t.Errorf("expected no HTTPServers queue entries, got %d", len(r2.HTTPServers.startQueue))
	}

	r3 := newRunnables(defaultBaseContext, errCh)
	if err := r3.Add(webhook.NewServer(webhook.Options{})); err != nil {
		t.Fatal(err)
	}
	if len(r3.Webhooks.startQueue) != 1 {
		t.Errorf("expected webhook in Webhooks group, got %d", len(r3.Webhooks.startQueue))
	}
}

